mapper.update:
update teaching_resource
name = #{name}, type = #{type}, path = #{path}, teacher_id = #{teacherId}, course_id = #{courseId}, upload_time = #{uploadTime}, description = #{description}, size = #{size}, downloads = #{downloads},
where id = #{id}

mapper.select:
select , t.name as teacherName, c.name as courseName from teaching_resource tr left join teacher t on tr.teacher_id = t.id left join course c on tr.course_id = c.id
and tr.id = #{id} and tr.name like concat('%', #{name}, '%') and tr.type like concat('%', #{type}, '%') and tr.teacher_id = #{teacherId} and tr.course_id = #{courseId}
order by tr.upload_time desc, tr.id desc
